insert into public.tree_species (slug, name, scientific_name, description, image_url, suitable_regions, care_notes, planting_cost, verification_fee, planter_payout, availability, emoji, native_to) values
  ('neem', 'Neem', 'Azadirachta indica', 'A hardy native tree that thrives in hot, dry Indian climates. Tolerant, low-maintenance, and long-lived.', 'https://images.unsplash.com/photo-1589025744528-4b36fdd5ed5d?auto=format&fit=crop&w=1200&q=80', '{madurai,coimbatore,bangalore,ahmedabad,jaipur,delhi}', 'Water weekly for the first 2 months, then seasonally. Clear weeds in a 1 m radius. Needs full sun.', 800, 100, 700, true, '🌳', 'Indian subcontinent'),
  ('mango', 'Mango', 'Mangifera indica', 'Beloved across India — a fruit + shade tree in one. Grows well in tropical to subtropical regions.', 'https://images.unsplash.com/photo-1553279768-865429fa0078?auto=format&fit=crop&w=1200&q=80', '{madurai,coimbatore,bangalore,mysore,kerala,pune}', 'Regular watering while young, then only in dry spells. Prune in the first 2–3 years.', 900, 100, 800, true, '🥭', 'South Asia'),
  ('banyan', 'Banyan', 'Ficus benghalensis', 'The national tree of India — its canopy shelters birds and its roots anchor riverbanks.', 'https://images.unsplash.com/photo-1509248961158-e54f6934749c?auto=format&fit=crop&w=1200&q=80', '{madurai,bangalore,kerala,delhi,nagpur,ahmedabad}', 'Needs open space for its future canopy. Water young trees weekly.', 850, 100, 750, true, '🌳', 'Indian subcontinent'),
  ('peepal', 'Peepal', 'Ficus religiosa', 'A culturally significant native tree with heart-shaped leaves and excellent shade.', 'https://images.unsplash.com/photo-1542273917363-3b1817f69a2d?auto=format&fit=crop&w=1200&q=80', '{madurai,jaipur,delhi,mysore,pune,kerala}', 'Fast-growing; water regularly in the first season. Roots are strong.', 780, 100, 680, true, '🌳', 'Indian subcontinent'),
  ('sheesham', 'Indian Rosewood (Sheesham)', 'Dalbergia sissoo', 'A sturdy timber tree suited to farm boundaries and river plains.', 'https://images.unsplash.com/photo-1503431128871-cd250803fa41?auto=format&fit=crop&w=1200&q=80', '{delhi,jaipur,nagpur,pune,bangalore}', 'Prefers sandy-loam soil. Needs good watering during the first two dry seasons.', 820, 100, 720, true, '🌲', 'South Asia'),
  ('golden-shower', 'Golden Shower (Amaltas)', 'Cassia fistula', 'A signature Indian flowering tree — cascades of golden blooms every summer.', 'https://images.unsplash.com/photo-1523712999610-f77fbcfc3843?auto=format&fit=crop&w=1200&q=80', '{madurai,coimbatore,ahmedabad,jaipur,kerala}', 'Drought tolerant but wants full sun. Trim for shape in late winter.', 760, 100, 660, true, '🌼', 'Indian subcontinent');